argv:
$ErrorActionPreference = 'Stop'
[Console]::InputEncoding = [System.Text.UTF8Encoding]::new($false)
[Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
$proc = $null
try {
  $spec = [Console]::In.ReadLine() | ConvertFrom-Json
  $targetId = [int]$spec.pid
  $proc = [System.Diagnostics.Process]::GetProcessById($targetId)
  $heldHandle = $proc.Handle
  $ticks = $proc.StartTime.ToUniversalTime().Ticks.ToString()
  $exe = $proc.MainModule.FileName
  $row = Get-CimInstance Win32_Process -Filter ("ProcessId=" + $targetId)
  if ($null -eq $row -or $proc.HasExited) { throw 'CDP browser is not a live process' }
  if ([int]$row.ProcessId -ne $targetId) { throw 'CIM PID mismatch' }
  if (-not [String]::Equals($exe,[string]$row.ExecutablePath,[StringComparison]::OrdinalIgnoreCase)) { throw 'CIM/process executable mismatch' }
  if ($proc.StartTime.ToUniversalTime().Ticks.ToString() -cne $ticks) { throw 'Process identity changed during capture' }
  [Console]::Out.WriteLine(([ordered]@{
    pid=$targetId;parentPid=[int]$row.ParentProcessId;executablePath=$exe;
    startTimeUtcTicks=$ticks;cimCreationTimeUtc=$row.CreationDate.ToUniversalTime().ToString('o');
    commandLine=[string]$row.CommandLine
  } | ConvertTo-Json -Compress))
  [Console]::Out.Flush()
} catch {
  [Console]::Error.WriteLine($_.Exception.Message)
  exit 2
} finally {
  if ($null -ne $proc) { $proc.Dispose() }
}
